// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address candidate) public {
        vm.assume(candidate != address(0));

        bool ok;
        vm.prank(candidate);
        try c.setOwner(candidate) returns (bool res) {
            ok = true;
        } catch {
            ok = false;
        }

        bool expectedOk = (candidate == address(this));
        assertTrue(ok == expectedOk);
    }
}
